import functools, time

def timed(fn):
    @functools.wraps(fn)
    def wrap(*a, **k):
        t = time.perf_counter()
        try: return fn(*a, **k)
        finally: print(fn.__name__, time.perf_counter() - t)
    return wrap

from typing import Protocol

class Reader(Protocol):
    def read(self) -> str: ...

def load(r: Reader) -> str:
